// Content für Google Docs API vorbereiten
const content = $('Parse Meta & Assemble Final').item.json.full_content;
const meta = $('Parse Meta & Assemble Final').item.json.meta;

// Header mit Meta-Daten + Content
const fullText = `META TITLE: ${meta.meta_title}\nMETA DESCRIPTION: ${meta.meta_description}\nURL SLUG: ${meta.url_slug}\nFOCUS KEYWORD: ${meta.focus_keyword}\n\n${'='.repeat(60)}\n\n${content}`;

return [{
  json: {
    doc_id: docId,
    doc_url: docUrl,
    full_text: fullText
  }
}];

// Zusammenfassung
const meta = $('Parse Meta & Assemble Final').item.json.meta;
const wordCount = $('Parse Meta & Assemble Final').item.json.word_count;
const docUrl = $('Prepare Doc Content').item.json.doc_url;
const keyword = $('Extract Input Data').item.json.keyword;

return [{
  json: {
    success: true,
    keyword: keyword,
    meta_title: meta.meta_title,
    meta_description: meta.meta_description,
    url_slug: meta.url_slug,
    word_count: wordCount,
    google_doc_url: docUrl,
    message: `Content für "${keyword}" erstellt (${wordCount} Wörter). Doc: ${docUrl}`
  }
}];

// WDF*IDF Abdeckungsprüfung für den gesamten Beitrag
const article = $('Extract Final Article').item.json.final_article.toLowerCase();
const wdfTermsRaw = $('Extract Input Data').item.json.wdf_idf_terms_json;
let wdfTerms;
try {
  wdfTerms = typeof wdfTermsRaw === 'string' ? JSON.parse(wdfTermsRaw) : wdfTermsRaw;
} catch(e) { wdfTerms = []; }

if (!wdfTerms || wdfTerms.length === 0) {
  return [{ json: { wdf_idf_check: 'Keine WDF*IDF Terme vorhanden', coverage_pct: 0, missing_terms: [], found_terms: [] } }];
}

const found = [];
const missing = [];
for (const t of wdfTerms) {
  const term = (t.term || t).toLowerCase();
  if (article.includes(term)) {
    found.push({ term, score: t.score || 0 });
  } else {
    missing.push({ term, score: t.score || 0 });
  }
}

const coveragePct = Math.round((found.length / wdfTerms.length) * 100);

// Top 15 fehlende Terme (nach Score sortiert)
const topMissing = missing.sort((a, b) => b.score - a.score).slice(0, 15);

return [{
  json: {
    coverage_pct: coveragePct,
    found_count: found.length,
    total_terms: wdfTerms.length,
    missing_count: missing.length,
    top_missing_terms: topMissing.map(t => `${t.term} (${t.score})`).join(', '),
    found_terms: found.map(t => t.term),
    needs_optimization: coveragePct < 60
  }
}];

